#include <iostream>
#include <iomanip>

int main() {
    int val = 100;

    // Using showbase, hex, internal justification, and fill character '*'
    std::cout << std::showbase << std::hex << std::internal
              << std::setw(10) << std::setfill('*') << val << "\n";

    // Reset justification, base, and fill character
    std::cout << std::dec << std::right << std::setfill(' ');
    std::cout << std::noshowbase << std::setw(10) << val << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    int hexVal = 0xabcdef;
    bool flag = true;

    // Uppercase hex and boolalpha string formatting
    std::cout << std::showbase << std::hex << std::uppercase << hexVal << "\n";
    std::cout << std::boolalpha << flag << "\n";

    // Reset uppercase, showbase, base, and boolalpha
    std::cout << std::nouppercase << hexVal << "\n";
    std::cout << std::dec << std::noshowbase << std::noboolalpha << flag << "\n";

    return 0;
}
